package auth
import("testing")
func TestStudentImportTargetRequiresLiveFullAdminSameOrganization(t *testing.T){a:=&Account{UserID:23,EntityID:73,Role:"admin",Organizations:[]Organization{{ID:11,Divisions:[]Division{{ID:17,Permissions:map[string]Permission{}},{ID:18,Permissions:map[string]Permission{}}}},{ID:12,Divisions:[]Division{{ID:19,Permissions:map[string]Permission{}}}}}};d:=int64(17);u,e:=a.User(ContextDTO{OrganizationID:11,DivisionID:&d});if e!=nil{t.Fatal(e)};v,e:=operationUserImportTarget(a,u,18);if e!=nil||*v.DivisionID!=18||v.OrganizationID!=11{t.Fatal("same organization target rejected",e)};if _,e=operationUserImportTarget(a,u,19);e==nil{t.Fatal("foreign organization accepted")};u.OrganizationAdmin=false;if _,e=operationUserImportTarget(a,u,18);e==nil{t.Fatal("unprivileged target accepted")}}
